import Foundation

/// What the About pane credits and the "Show License Texts…" sheet prints. Generated by
/// `scripts/acknowledgements.sh` from `Package.resolved`, the package checkouts and the
/// maintained `CollectiveKit/Acknowledgements/acknowledgements.json`, then bundled: a checked-in
/// resource instead of an Xcode build phase, which would change the project file, so `AcknowledgementsTests` is
/// what notices a pin the list does not follow.
public struct Acknowledgements: Sendable, Equatable, Decodable {
    /// One list in the pane. The resource names it by id; the title comes from the catalog.
    public struct Section: Sendable, Equatable, Decodable {
        public enum ID: String, Sendable, Equatable, Decodable {
            case libraries, fontsAndIcons, colorSchemes
        }

        public let id: ID
        public let entries: [Entry]

        public var title: LocalizedStringResource {
            switch id {
            case .libraries: SettingsText.libraries
            case .fontsAndIcons: SettingsText.fontsAndIcons
            case .colorSchemes: SettingsText.colorSchemes
            }
        }
    }

    /// One row: name, version, SPDX id and project link, plus the texts the license asks to ship.
    public struct Entry: Sendable, Equatable, Decodable {
        public let name: String
        /// A package's pinned version or a fixed release; `nil` for a scheme family, which
        /// shows `schemeCount`.
        public let version: String?
        /// How many bundled schemes the family has.
        public let schemeCount: Int?
        public let spdx: String
        /// The license's full name for the sheet, e.g. `MIT License` for `MIT`.
        public let license: String
        public let url: URL
        /// The identity in `Package.resolved`; `nil` for what is not a package.
        public let package: String?
        /// The bundled schemes this entry counts, by id prefix.
        public let schemeIDPrefix: String?
        /// The version column: the version as data, or the counted schemes in the catalog.
        public var versionText: LocalizedStringResource {
            schemeCount.map(Acknowledgements.schemeCountText) ?? .kit("%@", defaultValue: "\(version ?? "")")
        }

        /// Every license and NOTICE file, in the order the source has them.
        public let texts: [LicenseText]
    }

    /// One license or NOTICE file, verbatim.
    public struct LicenseText: Sendable, Equatable, Decodable {
        public let file: String
        public let text: String
    }

    /// One block of the sheet: a header such as `GRDB.swift 7.11.1 · MIT License` over the
    /// entry's texts.
    public struct LicenseDocument: Sendable, Equatable {
        public let header: String
        public let text: String
    }

    /// How the list differs from `Package.resolved`.
    public enum PackageMismatch: Sendable, Equatable {
        case version(identity: String, listed: String, pinned: String)
        /// Pinned, but not credited.
        case unlisted(identity: String)
        /// Credited as a package that is no longer pinned.
        case unpinned(identity: String)
    }

    public let sections: [Section]

    public static func schemeCountText(_ count: Int) -> LocalizedStringResource {
        .kit("%lld schemes", defaultValue: "\(count) schemes")
    }

    /// The resource in the kit's bundle. Stops when it is missing or malformed: it is part of
    /// the build, which `AcknowledgementsTests` checks before shipping.
    public static let bundled: Acknowledgements = {
        guard let url = Bundle.collectiveKit.url(forResource: "Acknowledgements", withExtension: "json") else {
            preconditionFailure("Acknowledgements.json is not bundled")
        }
        do {
            return try JSONDecoder().decode(Acknowledgements.self, from: Data(contentsOf: url))
        } catch {
            preconditionFailure("bundled Acknowledgements.json does not decode: \(error)")
        }
    }()

    /// The sheet's blocks, in list order; several files of one entry (a license and its NOTICE)
    /// form one block.
    public var licenseDocuments: [LicenseDocument] {
        sections.flatMap(\.entries).map { entry in
            LicenseDocument(
                header: "\(entry.name) \(String(localized: entry.versionText)) · \(entry.license)",
                text: entry.texts.map(\.text).joined(separator: "\n\n")
            )
        }
    }

    /// Differences to `pins`: pins in their order first, then listed packages no pin names.
    func packageMismatches(with pins: [PackagePin]) -> [PackageMismatch] {
        let listed = sections.flatMap(\.entries).compactMap { entry in
            entry.package.map { (identity: $0, version: entry.version ?? "") }
        }
        var mismatches: [PackageMismatch] = pins.compactMap { pin in
            guard let entry = listed.first(where: { $0.identity == pin.identity }) else {
                return .unlisted(identity: pin.identity)
            }
            return entry.version == pin.version
                ? nil : .version(identity: pin.identity, listed: entry.version, pinned: pin.version)
        }
        mismatches += listed
            .filter { entry in !pins.contains { $0.identity == entry.identity } }
            .map { .unpinned(identity: $0.identity) }
        return mismatches
    }
}

/// A pin in `Package.resolved`, as `scripts/acknowledgements.sh` reads it.
struct PackagePin: Equatable {
    let identity: String
    /// The tagged version, or the first seven characters of the revision for a branch pin.
    let version: String

    static func parse(_ data: Data) throws -> [PackagePin] {
        struct File: Decodable {
            struct Pin: Decodable {
                struct State: Decodable {
                    let revision: String
                    let version: String?
                }
                let identity: String
                let state: State
            }
            let pins: [Pin]
        }
        return try JSONDecoder().decode(File.self, from: data).pins.map { pin in
            PackagePin(identity: pin.identity, version: pin.state.version ?? String(pin.state.revision.prefix(7)))
        }
    }
}
